:root {
  --bg: #1b1b2f;
  --bg-accent: #23234a;
  --card: #2a2a4a;
  --ink: #f4f4ff;
  --muted: #b8b8d8;
  --accent: #ffd166;
  --accent-2: #ef476f;
  --ok: #06d6a0;
  --border: #0f0f1f;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background:
    linear-gradient(135deg, var(--bg) 0%, var(--bg-accent) 100%);
  background-attachment: fixed;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 16px;
  color: var(--ink);
}

.card {
  width: 100%;
  max-width: 440px;
  background: var(--card);
  border: 4px solid var(--border);
  border-radius: 0;
  box-shadow: 8px 8px 0 var(--border);
  padding: 28px 24px 32px;
  position: relative;
}

.card::before {
  content: "";
  position: absolute;
  inset: 6px;
  border: 2px dashed rgba(255, 209, 102, 0.25);
  pointer-events: none;
}

.title {
  margin: 0;
  font-size: 28px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 3px 3px 0 var(--border);
}

.subtitle {
  margin: 6px 0 24px;
  color: var(--muted);
  font-size: 16px;
}

.field {
  margin-bottom: 20px;
  border: 0;
  padding: 0;
}

label, legend {
  display: block;
  margin-bottom: 8px;
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--ink);
}

input[type="number"] {
  width: 100%;
  padding: 12px 14px;
  font-family: inherit;
  font-size: 18px;
  color: var(--ink);
  background: var(--bg);
  border: 3px solid var(--border);
  border-radius: 0;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

input[type="number"]::placeholder {
  color: var(--muted);
  opacity: 0.7;
}

input[type="number"]:hover {
  border-color: var(--accent);
}

input[type="number"]:focus-visible {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(255, 209, 102, 0.35);
}

.tip-buttons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.tip-btn {
  padding: 14px 8px;
  font-family: inherit;
  font-size: 18px;
  font-weight: 700;
  color: var(--ink);
  background: var(--bg);
  border: 3px solid var(--border);
  border-radius: 0;
  cursor: pointer;
  transition: transform 0.08s, background 0.15s, box-shadow 0.15s;
}

.tip-btn:hover {
  background: var(--bg-accent);
  border-color: var(--accent);
}

.tip-btn:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(255, 209, 102, 0.35);
}

.tip-btn:active {
  transform: translate(2px, 2px);
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  color: var(--border);
  border-color: var(--border);
  box-shadow: inset 0 0 0 3px var(--accent-2);
}

.error {
  min-height: 18px;
  margin: 6px 0 0;
  font-size: 14px;
  color: var(--accent-2);
}

.results {
  margin-top: 12px;
  padding: 18px 16px;
  background: var(--bg);
  border: 3px solid var(--border);
  box-shadow: inset 0 0 0 3px var(--bg-accent);
}

.result-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.result-row + .result-row {
  margin-top: 12px;
  padding-top: 12px;
  border-top: 2px dashed rgba(184, 184, 216, 0.3);
}

.result-label {
  font-size: 16px;
  color: var(--muted);
}

.result-value {
  font-size: 22px;
  font-weight: 700;
  color: var(--ok);
  letter-spacing: 1px;
}

@media (max-width: 400px) {
  body {
    padding: 16px 10px;
  }
  .card {
    padding: 22px 16px 26px;
    box-shadow: 5px 5px 0 var(--border);
  }
  .title {
    font-size: 24px;
  }
  .tip-buttons {
    gap: 8px;
  }
  .tip-btn {
    font-size: 16px;
    padding: 12px 4px;
  }
  .result-value {
    font-size: 20px;
  }
}

(function () {
  "use strict";

  var billInput = document.getElementById("bill");
  var peopleInput = document.getElementById("people");
  var tipButtons = Array.prototype.slice.call(document.querySelectorAll(".tip-btn"));
  var tipPerPersonEl = document.getElementById("tip-per-person");
  var totalPerPersonEl = document.getElementById("total-per-person");
  var billError = document.getElementById("bill-error");
  var peopleError = document.getElementById("people-error");
  var tipError = document.getElementById("tip-error");

  var selectedTip = null;

  function formatMoney(value) {
    return "$" + value.toFixed(2);
  }

  function parsePositive(value) {
    if (value === null || value.trim() === "") return null;
    var num = Number(value);
    if (!isFinite(num) || num < 0) return null;
    return num;
  }

  function parsePeople(value) {
    if (value === null || value.trim() === "") return null;
    var num = Number(value);
    if (!isFinite(num) || num < 1 || Math.floor(num) !== num) return null;
    return num;
  }

  function setText(el, text) {
    el.textContent = text;
  }

  function clearErrors() {
    setText(billError, "");
    setText(peopleError, "");
    setText(tipError, "");
  }

  function update() {
    clearErrors();

    var bill = parsePositive(billInput.value);
    var people = parsePeople(peopleInput.value);

    var hasBill = billInput.value.trim() !== "";
    var hasPeople = peopleInput.value.trim() !== "";

    if (hasBill && bill === null) {
      setText(billError, "Enter a valid bill amount (0 or more).");
    }
    if (hasPeople && people === null) {
      setText(peopleError, "Enter a whole number of people (1 or more).");
    }
    if (selectedTip === null) {
      setText(tipError, "Choose a tip percentage.");
    }

    if (bill === null || people === null || selectedTip === null) {
      setText(tipPerPersonEl, "$0.00");
      setText(totalPerPersonEl, "$0.00");
      return;
    }

    var tipTotal = bill * (selectedTip / 100);
    var total = bill + tipTotal;
    var tipPerPerson = tipTotal / people;
    var totalPerPerson = total / people;

    setText(tipPerPersonEl, formatMoney(tipPerPerson));
    setText(totalPerPersonEl, formatMoney(totalPerPerson));
  }

  tipButtons.forEach(function (btn) {
    btn.addEventListener("click", function () {
      var value = Number(btn.getAttribute("data-tip"));
      selectedTip = value;
      tipButtons.forEach(function (b) {
        b.setAttribute("aria-pressed", b === btn ? "true" : "false");
      });
      update();
    });

    btn.addEventListener("keydown", function (event) {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        btn.click();
      }
    });
  });

  billInput.addEventListener("input", update);
  peopleInput.addEventListener("input", update);

  var form = document.getElementById("tip-form");
  form.addEventListener("submit", function (event) {
    event.preventDefault();
    update();
  });

  update();
})();
